-- =====================================================================================================
-- Velexis OTA platform - CONTROL PLANE schema `platform` (PostgreSQL 16)
-- Shared by all OTAs (tenants). Holds portal accounts, tenants, memberships, billing, API keys, encrypted
-- supplier / payment-provider credentials, tenant schema migration state, provisioning jobs and audit.
-- It NEVER stores end-customer PII: customers, travellers, bookings live in the tenant_<key> schemas.
--
-- Conventions: text primary keys with a type prefix (acc_, asn_, ten_, dom_, stf_, ivt_, sub_, inv_, key_, sc_,
-- ppc_, job_) followed by a ULID generated by the application; timestamptz everywhere (UTC); money as
-- numeric(12,2) + char(3) ISO currency; status columns are text + CHECK lists (no PG enums, so new values are
-- an expand-only migration); `version` = optimistic-locking counter on mutable aggregates; secrets are stored
-- only as application-level envelope-encrypted ciphertext (bytea) + the id of the KMS key that wraps the DEK.
-- References to the `reference` schema (currency, country) are BY VALUE (no cross-schema foreign keys).
-- Trailing "-- " comments document each column (dictionary.json is generated from them, "* " = shown in ER).
-- =====================================================================================================

CREATE SCHEMA IF NOT EXISTS platform;

-- Velexis subscription plans that a tenant can be on (catalogue maintained by Velexis).
CREATE TABLE platform.plans (
  code               text PRIMARY KEY CHECK (code ~ '^[a-z][a-z0-9_]{1,39}$'),  -- * Natural key of the plan, e.g. starter, growth, enterprise.
  name               text NOT NULL,                                            -- * Display name of the plan.
  description        text,                                                     -- Marketing description shown on the pricing page.
  currency           char(3) NOT NULL DEFAULT 'EUR' CHECK (currency ~ '^[A-Z]{3}$'), -- ISO 4217 currency of the plan prices (by value to reference.currencies).
  monthly_price      numeric(12,2) NOT NULL DEFAULT 0 CHECK (monthly_price >= 0), -- Price per month when billed monthly.
  annual_price       numeric(12,2) CHECK (annual_price >= 0),                  -- Price per year when billed annually (NULL = no annual option).
  per_booking_fee    numeric(12,2) NOT NULL DEFAULT 0 CHECK (per_booking_fee >= 0), -- Usage fee charged per confirmed live booking above the included volume.
  included_bookings  integer NOT NULL DEFAULT 0 CHECK (included_bookings >= 0), -- Live bookings per billing period included in the base price.
  limits             jsonb NOT NULL DEFAULT '{}'::jsonb,                       -- Quotas, e.g. {"staffSeats":5,"apiKeys":10,"customDomains":1,"liveMode":true}.
  features           jsonb NOT NULL DEFAULT '{}'::jsonb,                       -- Feature flags unlocked by the plan, e.g. {"queues":true,"advancedSearch":true}.
  is_public          boolean NOT NULL DEFAULT true,                            -- Whether the plan is offered on the public sign-up page.
  is_active          boolean NOT NULL DEFAULT true,                            -- * False = legacy plan, kept for existing subscriptions only.
  sort_order         integer NOT NULL DEFAULT 0,                               -- Ordering on the pricing page.
  created_at         timestamptz NOT NULL DEFAULT now(),                       -- Row creation time.
  updated_at         timestamptz NOT NULL DEFAULT now()                        -- Last modification time.
);

-- People who sign up on the Velexis portal (OTA owners and staff). Staff identity of the console.
CREATE TABLE platform.accounts (
  id                    text PRIMARY KEY CHECK (id LIKE 'acc\_%'),             -- Account id (acc_ + ULID).
  email                 text NOT NULL CHECK (position('@' in email) > 1),     -- * Login e-mail of the portal user (unique case-insensitively).
  email_verified_at     timestamptz,                                         -- When the e-mail address was verified (NULL = not verified).
  password_hash         text,                                                -- Argon2id hash of the password (NULL when the account only uses SSO).
  full_name             text NOT NULL,                                       -- * Full name of the person.
  avatar_url            text,                                                -- Profile picture URL.
  locale                text NOT NULL DEFAULT 'en',                          -- Preferred UI locale of the portal/console (BCP 47).
  time_zone             text NOT NULL DEFAULT 'UTC',                         -- Preferred IANA time zone (by value to reference.time_zones).
  mfa_enabled           boolean NOT NULL DEFAULT false,                      -- Whether TOTP multi-factor authentication is required at login.
  mfa_secret_ciphertext bytea,                                               -- Envelope-encrypted TOTP secret (NULL when MFA is disabled).
  encryption_key_id     text,                                                -- KMS key id that wraps the data key of mfa_secret_ciphertext.
  status                text NOT NULL DEFAULT 'pending_verification'
                        CHECK (status IN ('pending_verification','active','locked','disabled','deleted')), -- * Lifecycle state of the account.
  is_platform_admin     boolean NOT NULL DEFAULT false,                      -- Velexis operator with access to the platform back-office.
  failed_login_count    integer NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0), -- Consecutive failed logins (reset on success; drives lockout).
  locked_until          timestamptz,                                         -- Temporary lockout end after too many failed logins.
  last_login_at         timestamptz,                                         -- Last successful login.
  deleted_at            timestamptz,                                         -- When the account was erased/anonymised (status = deleted).
  version               integer NOT NULL DEFAULT 1,                          -- Optimistic-locking counter, incremented on every update.
  created_at            timestamptz NOT NULL DEFAULT now(),                  -- * Sign-up time.
  updated_at            timestamptz NOT NULL DEFAULT now()                   -- Last modification time.
);
CREATE UNIQUE INDEX accounts_email_lower_uq ON platform.accounts (lower(email));

-- OTAs. Each tenant row owns exactly one PostgreSQL schema tenant_<key> holding all of its data.
CREATE TABLE platform.tenants (
  id                    text PRIMARY KEY CHECK (id LIKE 'ten\_%'),             -- Tenant id (ten_ + ULID).
  key                   text NOT NULL UNIQUE
                        CHECK (key ~ '^[a-z][a-z0-9_]{1,39}$' AND key NOT IN ('platform','reference','public','admin','api','www','app','console')), -- * Immutable short key; used for the schema name and the <key>.velexis.app host.
  schema_name           text GENERATED ALWAYS AS ('tenant_' || key) STORED UNIQUE, -- * Name of the tenant schema (always tenant_<key>).
  name                  text NOT NULL,                                       -- * Display name of the OTA.
  legal_name            text,                                                -- Legal entity name used on invoices.
  status                text NOT NULL DEFAULT 'provisioning'
                        CHECK (status IN ('provisioning','active','suspended','deprovisioning','deleted','failed')), -- * Lifecycle; only active tenants are served.
  plan_code             text NOT NULL REFERENCES platform.plans (code) ON DELETE RESTRICT, -- Current plan (denormalised from the active subscription).
  region                text NOT NULL DEFAULT 'eu-west-1',                   -- * Data residency region of the tenant.
  cluster               text NOT NULL DEFAULT 'pg-eu-1',                     -- * PostgreSQL cluster that hosts the tenant schema (shard key for routing).
  default_currency      char(3) NOT NULL DEFAULT 'EUR' CHECK (default_currency ~ '^[A-Z]{3}$'), -- Default selling currency (by value to reference.currencies).
  default_locale        text NOT NULL DEFAULT 'en',                          -- Default storefront locale (BCP 47).
  time_zone             text NOT NULL DEFAULT 'UTC',                         -- Business time zone for reports and ticketing deadlines.
  country_code          char(2) CHECK (country_code ~ '^[A-Z]{2}$'),         -- Country where the OTA is registered (by value to reference.countries).
  support_email         text,                                                -- Business support e-mail of the OTA (not end-customer data).
  schema_version        text,                                                -- * Latest tenant migration applied to the schema (mirror of tenant_schema_migrations).
  created_by_account_id text REFERENCES platform.accounts (id) ON DELETE SET NULL, -- Portal account that signed up and created the OTA.
  activated_at          timestamptz,                                         -- When provisioning finished and the tenant became active.
  suspended_at          timestamptz,                                         -- When the tenant was suspended (NULL unless suspended).
  suspension_reason     text,                                                -- Why the tenant was suspended (billing, abuse, request).
  deleted_at            timestamptz,                                         -- When the tenant schema was dropped after export/retention.
  metadata              jsonb NOT NULL DEFAULT '{}'::jsonb,                  -- Free-form platform metadata (sales notes, onboarding flags).
  version               integer NOT NULL DEFAULT 1,                          -- Optimistic-locking counter.
  created_at            timestamptz NOT NULL DEFAULT now(),                  -- * Creation (sign-up) time.
  updated_at            timestamptz NOT NULL DEFAULT now()                   -- Last modification time.
);
CREATE INDEX tenants_status_idx ON platform.tenants (status, cluster);
CREATE INDEX tenants_created_by_idx ON platform.tenants (created_by_account_id);
CREATE INDEX tenants_plan_idx ON platform.tenants (plan_code);
CREATE INDEX tenants_name_lower_idx ON platform.tenants (lower(name) text_pattern_ops);

-- Portal login sessions of accounts (rotating refresh tokens of the portal/console).
CREATE TABLE platform.account_sessions (
  id                 text PRIMARY KEY CHECK (id LIKE 'asn\_%'),               -- Session id (asn_ + ULID); one row per refresh token generation.
  account_id         text NOT NULL REFERENCES platform.accounts (id) ON DELETE CASCADE, -- * Account that owns the session.
  active_tenant_id   text REFERENCES platform.tenants (id) ON DELETE SET NULL, -- OTA currently selected in the console for this session.
  refresh_token_hash text NOT NULL UNIQUE,                                   -- SHA-256 of the opaque refresh token (the token itself is never stored).
  family_id          text NOT NULL,                                          -- * Rotation family: all tokens issued from one login; reuse of a rotated token revokes the family.
  replaced_by_id     text REFERENCES platform.account_sessions (id) ON DELETE SET NULL, -- Next token of the rotation chain.
  user_agent         text,                                                   -- User agent at login.
  ip_address         inet,                                                   -- Client IP at login.
  expires_at         timestamptz NOT NULL,                                   -- * Refresh token expiry.
  last_used_at       timestamptz,                                            -- Last refresh with this token.
  rotated_at         timestamptz,                                            -- When the token was exchanged for a new one.
  revoked_at         timestamptz,                                            -- When the session was revoked.
  revoke_reason      text CHECK (revoke_reason IN ('logout','rotation_reuse','password_change','admin','expired')), -- Why it was revoked.
  created_at         timestamptz NOT NULL DEFAULT now(),                     -- Login time.
  updated_at         timestamptz NOT NULL DEFAULT now()                      -- Last modification time.
);
CREATE INDEX account_sessions_account_idx ON platform.account_sessions (account_id) WHERE revoked_at IS NULL;
CREATE INDEX account_sessions_family_idx ON platform.account_sessions (family_id);
CREATE INDEX account_sessions_expires_idx ON platform.account_sessions (expires_at);
CREATE INDEX account_sessions_tenant_idx ON platform.account_sessions (active_tenant_id) WHERE active_tenant_id IS NOT NULL;
CREATE INDEX account_sessions_replaced_by_idx ON platform.account_sessions (replaced_by_id) WHERE replaced_by_id IS NOT NULL;

-- Host names that route to a tenant: <key>.velexis.app sub-domains and verified custom domains.
CREATE TABLE platform.tenant_domains (
  id                  text PRIMARY KEY CHECK (id LIKE 'dom\_%'),             -- Domain id (dom_ + ULID).
  tenant_id           text NOT NULL REFERENCES platform.tenants (id) ON DELETE CASCADE, -- * Tenant served on this host.
  hostname            text NOT NULL CHECK (hostname = lower(hostname)),      -- * Fully qualified host name, lower case (unique).
  kind                text NOT NULL CHECK (kind IN ('subdomain','custom')),  -- * Velexis sub-domain or customer-owned domain.
  purpose             text NOT NULL DEFAULT 'storefront' CHECK (purpose IN ('storefront','api','console')), -- What the host serves.
  is_primary          boolean NOT NULL DEFAULT false,                        -- Primary host for this purpose (used in e-mails and links).
  verification_status text NOT NULL DEFAULT 'pending' CHECK (verification_status IN ('pending','verified','failed')), -- * DNS ownership verification state.
  verification_token  text,                                                  -- Value expected in the DNS TXT record.
  verified_at         timestamptz,                                           -- When DNS ownership was verified.
  tls_status          text NOT NULL DEFAULT 'pending' CHECK (tls_status IN ('pending','issued','failed','expired')), -- TLS certificate state.
  tls_expires_at      timestamptz,                                           -- Certificate expiry (renewal job).
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- Row creation time.
  updated_at          timestamptz NOT NULL DEFAULT now()                     -- Last modification time.
);
CREATE UNIQUE INDEX tenant_domains_hostname_uq ON platform.tenant_domains (hostname);
CREATE UNIQUE INDEX tenant_domains_primary_uq ON platform.tenant_domains (tenant_id, purpose) WHERE is_primary;

-- Staff of an OTA: membership of a portal account in a tenant with a console role. id is the staff id (stf_).
CREATE TABLE platform.tenant_memberships (
  id                    text PRIMARY KEY CHECK (id LIKE 'stf\_%'),             -- Staff id (stf_ + ULID); subject of staff tokens, referenced by value in tenant staff_actions.
  tenant_id             text NOT NULL REFERENCES platform.tenants (id) ON DELETE CASCADE, -- * OTA.
  account_id            text NOT NULL REFERENCES platform.accounts (id) ON DELETE CASCADE, -- * Portal account.
  role                  text NOT NULL CHECK (role IN ('owner','admin','agent','finance','viewer')), -- * Console role of the account in this OTA.
  status                text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','removed')), -- * Membership state.
  invited_by_account_id text REFERENCES platform.accounts (id) ON DELETE SET NULL, -- Who invited this member (NULL for the founder).
  last_active_at        timestamptz,                                         -- Last console activity in this tenant.
  version               integer NOT NULL DEFAULT 1,                          -- Optimistic-locking counter.
  created_at            timestamptz NOT NULL DEFAULT now(),                  -- Row creation time.
  updated_at            timestamptz NOT NULL DEFAULT now(),                  -- Last modification time.
  CONSTRAINT tenant_memberships_tenant_account_uq UNIQUE (tenant_id, account_id)
);
CREATE INDEX tenant_memberships_account_idx ON platform.tenant_memberships (account_id) WHERE status = 'active';

-- Pending invitations of people (by e-mail) to join an OTA's staff.
CREATE TABLE platform.tenant_invitations (
  id                    text PRIMARY KEY CHECK (id LIKE 'ivt\_%'),             -- Invitation id (ivt_ + ULID).
  tenant_id             text NOT NULL REFERENCES platform.tenants (id) ON DELETE CASCADE, -- * OTA the person is invited to.
  email                 text NOT NULL,                                       -- * Invitee e-mail (staff, not end customer).
  role                  text NOT NULL CHECK (role IN ('owner','admin','agent','finance','viewer')), -- * Role granted on acceptance.
  token_hash            text NOT NULL UNIQUE,                                -- SHA-256 of the invitation token sent by e-mail.
  status                text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','revoked','expired')), -- * Invitation state.
  invited_by_account_id text REFERENCES platform.accounts (id) ON DELETE SET NULL, -- Account that sent the invitation.
  accepted_account_id   text REFERENCES platform.accounts (id) ON DELETE SET NULL, -- Account that accepted it.
  expires_at            timestamptz NOT NULL,                                -- Invitation expiry.
  accepted_at           timestamptz,                                         -- Acceptance time.
  revoked_at            timestamptz,                                         -- Revocation time.
  created_at            timestamptz NOT NULL DEFAULT now(),                  -- Row creation time.
  updated_at            timestamptz NOT NULL DEFAULT now()                   -- Last modification time.
);
CREATE UNIQUE INDEX tenant_invitations_pending_uq ON platform.tenant_invitations (tenant_id, lower(email)) WHERE status = 'pending';

-- Billing subscription of a tenant to a plan (one current subscription per tenant).
CREATE TABLE platform.subscriptions (
  id                       text PRIMARY KEY CHECK (id LIKE 'sub\_%'),          -- Subscription id (sub_ + ULID).
  tenant_id                text NOT NULL REFERENCES platform.tenants (id) ON DELETE RESTRICT, -- * Subscribed tenant (billing records are never cascaded away).
  plan_code                text NOT NULL REFERENCES platform.plans (code) ON DELETE RESTRICT, -- * Subscribed plan.
  status                   text NOT NULL CHECK (status IN ('trialing','active','past_due','paused','canceled','incomplete')), -- * Billing state.
  billing_interval         text NOT NULL DEFAULT 'month' CHECK (billing_interval IN ('month','year')), -- Billing period length.
  billing_provider         text NOT NULL DEFAULT 'stripe' CHECK (billing_provider IN ('stripe','manual')), -- Who bills Velexis fees.
  provider_customer_id     text,                                             -- Customer id at the billing provider.
  provider_subscription_id text,                                             -- Subscription id at the billing provider.
  billing_email            text,                                             -- Where invoices are sent (OTA finance contact).
  trial_ends_at            timestamptz,                                      -- End of the free trial.
  current_period_start     timestamptz,                                      -- Start of the current billing period.
  current_period_end       timestamptz,                                      -- * End of the current billing period.
  cancel_at_period_end     boolean NOT NULL DEFAULT false,                   -- Cancellation scheduled at period end.
  canceled_at              timestamptz,                                      -- When it was canceled.
  version                  integer NOT NULL DEFAULT 1,                       -- Optimistic-locking counter.
  created_at               timestamptz NOT NULL DEFAULT now(),               -- Row creation time.
  updated_at               timestamptz NOT NULL DEFAULT now()                -- Last modification time.
);
CREATE UNIQUE INDEX subscriptions_current_uq ON platform.subscriptions (tenant_id) WHERE status IN ('trialing','active','past_due','paused','incomplete');
CREATE INDEX subscriptions_plan_idx ON platform.subscriptions (plan_code);
CREATE UNIQUE INDEX subscriptions_provider_uq ON platform.subscriptions (billing_provider, provider_subscription_id) WHERE provider_subscription_id IS NOT NULL;

-- Velexis invoices issued to tenants (platform fees, per-booking usage).
CREATE TABLE platform.invoices (
  id                  text PRIMARY KEY CHECK (id LIKE 'inv\_%'),             -- Invoice id (inv_ + ULID).
  tenant_id           text NOT NULL REFERENCES platform.tenants (id) ON DELETE RESTRICT, -- * Billed tenant.
  subscription_id     text REFERENCES platform.subscriptions (id) ON DELETE SET NULL, -- Subscription the invoice belongs to.
  number              text NOT NULL UNIQUE,                                  -- * Sequential legal invoice number.
  status              text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','open','paid','void','uncollectible')), -- * Invoice state.
  currency            char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),      -- Invoice currency.
  subtotal            numeric(12,2) NOT NULL DEFAULT 0,                      -- Sum of line items before tax.
  tax_amount          numeric(12,2) NOT NULL DEFAULT 0,                      -- VAT / sales tax.
  total               numeric(12,2) NOT NULL DEFAULT 0,                      -- * Total amount (subtotal + tax).
  amount_paid         numeric(12,2) NOT NULL DEFAULT 0,                      -- Amount already paid.
  amount_due          numeric(12,2) NOT NULL DEFAULT 0,                      -- Remaining amount due.
  period_start        timestamptz,                                           -- Billed period start.
  period_end          timestamptz,                                           -- Billed period end.
  line_items          jsonb NOT NULL DEFAULT '[]'::jsonb,                    -- Lines: plan fee, booking usage (count x fee), adjustments.
  provider_invoice_id text,                                                  -- Invoice id at the billing provider.
  pdf_storage_key     text,                                                  -- Object-storage key of the PDF.
  issued_at           timestamptz,                                           -- Issue date.
  due_at              timestamptz,                                           -- Payment due date.
  paid_at             timestamptz,                                           -- When fully paid.
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- Row creation time.
  updated_at          timestamptz NOT NULL DEFAULT now(),                    -- Last modification time.
  CONSTRAINT invoices_total_ck CHECK (total = subtotal + tax_amount)
);
CREATE INDEX invoices_tenant_idx ON platform.invoices (tenant_id, issued_at DESC);
CREATE INDEX invoices_subscription_idx ON platform.invoices (subscription_id) WHERE subscription_id IS NOT NULL;
CREATE UNIQUE INDEX invoices_provider_uq ON platform.invoices (provider_invoice_id) WHERE provider_invoice_id IS NOT NULL;

-- API keys of tenants (X-Api-Key). Only a hash is stored; the prefix identifies kind + environment.
CREATE TABLE platform.api_keys (
  id                    text PRIMARY KEY CHECK (id LIKE 'key\_%'),             -- API key id (key_ + ULID).
  tenant_id             text REFERENCES platform.tenants (id) ON DELETE CASCADE, -- * Tenant resolved from the key (NULL only for hosting keys, which act for the OTAs in api_key_tenant_grants).
  owner_account_id      text REFERENCES platform.accounts (id) ON DELETE CASCADE, -- Portal account that owns a hosting key (required for kind hosting, NULL otherwise).
  name                  text NOT NULL,                                       -- Label given in the portal (e.g. "Storefront prod").
  kind                  text NOT NULL CHECK (kind IN ('publishable','secret','hosting')), -- * pk_ (browser-safe, customer scope), sk_ (server-only) or hk_ (server-only, one deployment serving several OTA domains; requires X-Velexis-Host).
  environment           text NOT NULL CHECK (environment IN ('test','live')), -- * test = Amadeus test connection, live = production.
  prefix                text NOT NULL UNIQUE,                                -- * Visible lookup prefix, e.g. pk_live_3fA9x2 (first 14 chars of the key).
  key_hash              text NOT NULL UNIQUE,                                -- HMAC-SHA-256 of the full key with a server pepper.
  last4                 char(4) NOT NULL,                                    -- Last 4 characters, shown in the portal.
  allowed_origins       text[] NOT NULL DEFAULT '{}',                        -- Browser origin allow-list (publishable keys only).
  scopes                text[] NOT NULL DEFAULT '{}',                        -- Key scopes: storefront (refused on every console operation), console (console calls with a staff token), console:automation plus explicit permissions such as bookings:issue (key-only console calls get exactly these). Empty = customer scope + console with a staff token; never key-only console access.
  created_by_account_id text REFERENCES platform.accounts (id) ON DELETE SET NULL, -- Who created the key (NULL = provisioning).
  revoked_by_account_id text REFERENCES platform.accounts (id) ON DELETE SET NULL, -- Who revoked it.
  last_used_at          timestamptz,                                         -- Last authenticated request (updated asynchronously).
  last_used_ip          inet,                                                -- Client IP of the last request.
  expires_at            timestamptz,                                         -- Optional expiry (rolling keys).
  revoked_at            timestamptz,                                         -- * Revocation time (NULL = valid).
  created_at            timestamptz NOT NULL DEFAULT now(),                  -- Row creation time.
  updated_at            timestamptz NOT NULL DEFAULT now(),                  -- Last modification time.
  CONSTRAINT api_keys_prefix_ck CHECK (prefix ~ ('^' || CASE kind WHEN 'publishable' THEN 'pk' WHEN 'hosting' THEN 'hk' ELSE 'sk' END || '_' || environment || '_[A-Za-z0-9]+$')),
  CONSTRAINT api_keys_owner_ck CHECK ((kind = 'hosting') = (tenant_id IS NULL) AND (kind = 'hosting') = (owner_account_id IS NOT NULL)),
  CONSTRAINT api_keys_origins_ck CHECK (kind = 'publishable' OR cardinality(allowed_origins) = 0)
);
CREATE INDEX api_keys_tenant_idx ON platform.api_keys (tenant_id, environment) WHERE revoked_at IS NULL;

-- OTAs a hosting key (hk_) may act for; the request's X-Velexis-Host must be a verified domain of one of them.
CREATE TABLE platform.api_key_tenant_grants (
  api_key_id            text NOT NULL REFERENCES platform.api_keys (id) ON DELETE CASCADE, -- * Hosting key.
  tenant_id             text NOT NULL REFERENCES platform.tenants (id) ON DELETE CASCADE,  -- * OTA the key may act for.
  granted_by_account_id text REFERENCES platform.accounts (id) ON DELETE SET NULL,          -- Owner/admin of the OTA who granted it.
  created_at            timestamptz NOT NULL DEFAULT now(),                                 -- Grant time.
  updated_at            timestamptz NOT NULL DEFAULT now(),                                 -- Last modification time.
  PRIMARY KEY (api_key_id, tenant_id)
);
CREATE INDEX api_key_tenant_grants_tenant_idx ON platform.api_key_tenant_grants (tenant_id);

-- Amadeus Enterprise credentials of a tenant, one per environment (test / live).
CREATE TABLE platform.supplier_connections (
  id                       text PRIMARY KEY CHECK (id LIKE 'sc\_%'),           -- Connection id (sc_ + ULID).
  tenant_id                text NOT NULL REFERENCES platform.tenants (id) ON DELETE CASCADE, -- * Owning tenant.
  provider                 text NOT NULL DEFAULT 'amadeus' CHECK (provider IN ('amadeus')), -- * Supplier (Amadeus Enterprise flight APIs).
  environment              text NOT NULL CHECK (environment IN ('test','live')), -- * test -> test.travel.api.amadeus.com, live -> travel.api.amadeus.com.
  base_url                 text NOT NULL,                                    -- API host used for this connection.
  client_id                text NOT NULL,                                    -- * OAuth2 client id (API key) issued by Amadeus.
  client_secret_ciphertext bytea NOT NULL,                                   -- Envelope-encrypted OAuth2 client secret.
  encryption_key_id        text NOT NULL,                                    -- KMS key id that wraps the data key of the secret.
  office_ids               text[] NOT NULL DEFAULT '{}',                     -- Amadeus office ids the credentials may act for (e.g. NCE1A0955).
  default_office_id        text,                                             -- * Office used when the caller does not choose one (queues, PNR lookup).
  queuing_office_id        text,                                             -- Default flight-order queuingOfficeId.
  owner_office_id          text,                                             -- Default flight-order ownerOfficeId.
  ticketing_defaults       jsonb NOT NULL DEFAULT '{}'::jsonb,               -- Defaults for create-order: ticketingAgreement {option,delay}, automatedProcess, issue flag.
  monitored_queues         jsonb NOT NULL DEFAULT '[]'::jsonb,               -- Queues polled into queue_snapshots: [{officeId, queueId, category}].
  status                   text NOT NULL DEFAULT 'pending_verification'
                           CHECK (status IN ('pending_verification','active','invalid_credentials','disabled')), -- * Connection health.
  last_verified_at         timestamptz,                                      -- Last successful token request.
  last_error               text,                                             -- Last verification error (no secrets).
  created_by_account_id    text REFERENCES platform.accounts (id) ON DELETE SET NULL, -- Who configured it.
  version                  integer NOT NULL DEFAULT 1,                       -- Optimistic-locking counter.
  created_at               timestamptz NOT NULL DEFAULT now(),               -- Row creation time.
  updated_at               timestamptz NOT NULL DEFAULT now(),               -- Last modification time.
  CONSTRAINT supplier_connections_env_uq UNIQUE (tenant_id, provider, environment)
);

-- Payment service provider accounts of a tenant (the OTA collects payments from its customers).
CREATE TABLE platform.payment_provider_connections (
  id                        text PRIMARY KEY CHECK (id LIKE 'ppc\_%'),       -- Connection id (ppc_ + ULID).
  tenant_id                 text NOT NULL REFERENCES platform.tenants (id) ON DELETE CASCADE, -- * Owning tenant.
  provider                  text NOT NULL CHECK (provider IN ('stripe','adyen','checkout_com','paypal','manual')), -- * Payment service provider.
  environment               text NOT NULL CHECK (environment IN ('test','live')), -- * Matches the API key environment.
  account_reference         text,                                            -- Merchant / connected account id at the provider.
  publishable_key           text,                                            -- Public client key (safe in the browser).
  secret_ciphertext         bytea,                                           -- Envelope-encrypted secret API key.
  webhook_secret_ciphertext bytea,                                           -- Envelope-encrypted webhook signing secret.
  encryption_key_id         text,                                            -- KMS key id wrapping the data keys of the secrets.
  supported_methods         text[] NOT NULL DEFAULT '{card}',                -- Enabled methods (card, apple_pay, google_pay, paypal, bank_transfer).
  capture_mode              text NOT NULL DEFAULT 'manual' CHECK (capture_mode IN ('automatic','manual')), -- manual = authorise, capture after the booking succeeded.
  is_default                boolean NOT NULL DEFAULT true,                   -- Default connection for the environment.
  status                    text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','disabled','error')), -- * Connection health.
  last_verified_at          timestamptz,                                     -- Last successful credential check.
  version                   integer NOT NULL DEFAULT 1,                      -- Optimistic-locking counter.
  created_at                timestamptz NOT NULL DEFAULT now(),              -- Row creation time.
  updated_at                timestamptz NOT NULL DEFAULT now(),              -- Last modification time.
  CONSTRAINT payment_provider_connections_uq UNIQUE (tenant_id, provider, environment)
);
CREATE UNIQUE INDEX payment_provider_connections_default_uq ON platform.payment_provider_connections (tenant_id, environment) WHERE is_default;

-- Tenant migration ledger: which migration version ran in which tenant schema (mirror of each schema's schema_migrations).
CREATE TABLE platform.tenant_schema_migrations (
  tenant_id   text NOT NULL REFERENCES platform.tenants (id) ON DELETE CASCADE, -- * Tenant whose schema was migrated.
  version     text NOT NULL CHECK (version ~ '^[0-9]{4,14}(_[a-z0-9_]+)?$'),  -- * Migration version, e.g. 0001_baseline.
  schema_name text NOT NULL,                                                 -- * Schema the migration ran in (tenant_<key>).
  checksum    text NOT NULL,                                                 -- SHA-256 of the migration file (detects edited migrations).
  phase       text NOT NULL DEFAULT 'expand' CHECK (phase IN ('expand','migrate','contract')), -- Expand/contract phase of the change.
  status      text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','running','applied','failed','rolled_back')), -- * Outcome for this schema.
  runner_id   text,                                                          -- Deployment / job that ran it.
  started_at  timestamptz,                                                   -- Start time.
  finished_at timestamptz,                                                   -- End time.
  duration_ms integer,                                                       -- Execution time in milliseconds.
  error       text,                                                          -- Error message when failed.
  created_at  timestamptz NOT NULL DEFAULT now(),                            -- Row creation time.
  updated_at  timestamptz NOT NULL DEFAULT now(),                            -- Last modification time.
  PRIMARY KEY (tenant_id, version)
);
CREATE INDEX tenant_schema_migrations_status_idx ON platform.tenant_schema_migrations (version, status);

-- Asynchronous tenant lifecycle jobs (provision, migrate, export, delete ...), leased by workers.
CREATE TABLE platform.provisioning_jobs (
  id                      text PRIMARY KEY CHECK (id LIKE 'job\_%'),         -- Job id (job_ + ULID).
  tenant_id               text NOT NULL REFERENCES platform.tenants (id) ON DELETE CASCADE, -- * Target tenant.
  kind                    text NOT NULL CHECK (kind IN ('provision','migrate','suspend','resume','export','delete','restore','rotate_secrets')), -- * Job type.
  status                  text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','succeeded','failed','canceled')), -- * Job state.
  step                    text,                                              -- * Current step, e.g. create_schema, run_migrations, seed_defaults, issue_api_keys, activate.
  steps                   jsonb NOT NULL DEFAULT '[]'::jsonb,                -- Step log: [{step, status, startedAt, finishedAt, error}].
  payload                 jsonb NOT NULL DEFAULT '{}'::jsonb,                -- Job input (e.g. target version, export format).
  result                  jsonb,                                             -- Job output (e.g. export storage key, created API key ids).
  attempt                 integer NOT NULL DEFAULT 0,                        -- Attempts made so far.
  max_attempts            integer NOT NULL DEFAULT 5,                        -- Retry budget.
  scheduled_at            timestamptz NOT NULL DEFAULT now(),                -- Earliest start (retry backoff).
  locked_by               text,                                              -- Worker holding the lease.
  locked_until            timestamptz,                                       -- Lease expiry (another worker may take over after it).
  started_at              timestamptz,                                       -- First start.
  finished_at             timestamptz,                                       -- Completion time.
  error                   text,                                              -- Last error.
  requested_by_account_id text REFERENCES platform.accounts (id) ON DELETE SET NULL, -- Who requested it (NULL = system).
  created_at              timestamptz NOT NULL DEFAULT now(),                -- Row creation time.
  updated_at              timestamptz NOT NULL DEFAULT now()                 -- Last modification time.
);
CREATE UNIQUE INDEX provisioning_jobs_active_uq ON platform.provisioning_jobs (tenant_id, kind) WHERE status IN ('queued','running');
CREATE INDEX provisioning_jobs_queue_idx ON platform.provisioning_jobs (scheduled_at) WHERE status = 'queued';

-- Append-only audit trail of control-plane actions (sign-up, key creation, credential changes, suspensions).
CREATE TABLE platform.platform_audit_log (
  id               bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,          -- Monotonic audit entry id.
  tenant_id        text REFERENCES platform.tenants (id) ON DELETE SET NULL, -- * Tenant concerned (NULL for account-level events).
  tenant_key       text,                                                     -- Snapshot of the tenant key (kept after tenant deletion).
  actor_type       text NOT NULL CHECK (actor_type IN ('account','platform_admin','api_key','system')), -- * Who acted.
  actor_account_id text REFERENCES platform.accounts (id) ON DELETE SET NULL, -- Acting account.
  actor_label      text,                                                     -- Snapshot of the actor (e-mail, key prefix or job name).
  action           text NOT NULL,                                            -- * Dotted action name, e.g. api_key.revoked, tenant.suspended.
  target_type      text,                                                     -- Type of the affected object (tenant, api_key, supplier_connection ...).
  target_id        text,                                                     -- Id of the affected object.
  request_id       text,                                                     -- X-Request-Id of the HTTP request.
  ip_address       inet,                                                     -- Client IP.
  user_agent       text,                                                     -- Client user agent.
  details          jsonb NOT NULL DEFAULT '{}'::jsonb,                       -- Before/after values (secrets redacted).
  created_at       timestamptz NOT NULL DEFAULT now()                        -- * When it happened.
);
CREATE INDEX platform_audit_log_tenant_idx ON platform.platform_audit_log (tenant_id, created_at DESC);
CREATE INDEX platform_audit_log_actor_idx ON platform.platform_audit_log (actor_account_id, created_at DESC);
CREATE INDEX platform_audit_log_action_idx ON platform.platform_audit_log (action, created_at DESC);
